        int ans = 0;
        long rightSum = 0;
        for (int i = n - 1; i >= 0; i--) {
            int rightCount = n - 1 - i;
            if (rightCount > 0 && (long) nums[i] * rightCount > rightSum) {
                ans++;
            }
            rightSum += nums[i];
